ctions": [{"other_code": "N_3482bc2be7600a0c", "rule": "本节点关注空间维度复用（多芯/多模）；兄弟节点关注单模光纤中的强度调制与检测机制。"}, {"other_code": "N_ad601f0d5dbd106e", "rule": "本节点关注空间维度复用（多芯/多模）；兄弟节点关注单模光纤中的相干调制与解调技术。"}], "cross_boundary_rule": "空分复用系统中的MIMO信号处理算法若独立于光纤物理特性，可关联信号处理节点；但针对模式串扰、模式耦合的光信道特性分析归入本节点。"}]}
